 static final class State{long now=System.currentTimeMillis(),at,prev;long[] ts;int next,previous;String[] names;String city,day,hijri,greg,hmonth,gmonth,hday,gday,hyear,gyear,code;boolean rtl;}
 static State state(Context c)throws Exception{State s=new State();s.code=lang(c);s.rtl=rtl(c);com.example.ui.i18n.L10n.INSTANCE.init(c);Locale l=new Locale(s.code);Calendar day=Calendar.getInstance();s.ts=times(c,day);com.example.ui.i18n.L10n lx=com.example.ui.i18n.L10n.INSTANCE;s.names=new String[]{lx.t(com.example.ui.i18n.S.PrayerFajr),lx.t(com.example.ui.i18n.S.PrayerShuruq),lx.t(com.example.ui.i18n.S.PrayerDhuhr),lx.t(com.example.ui.i18n.S.PrayerAsr),lx.t(com.example.ui.i18n.S.PrayerMaghrib),lx.t(com.example.ui.i18n.S.PrayerIsha)};s.next=-1;for(int i=0;i<6;i++)if(i!=1&&s.ts[i]>s.now){s.next=i;break;}if(s.next<0){Calendar t=(Calendar)day.clone();t.add(Calendar.DATE,1);s.at=times(c,t)[0];s.next=0;s.prev=s.ts[5];s.previous=5;}else{s.at=s.ts[s.next];s.previous=s.next==2?0:s.next-1;if(s.next==0){Calendar y=(Calendar)day.clone();y.add(Calendar.DATE,-1);s.prev=times(c,y)[5];s.previous=5;}else s.prev=s.ts[s.previous];}s.city=(String)Class.forName("com.example.fajr.data.FajrPreferences").getMethod("getCityNameLocalized",String.class).invoke(Class.forName("com.example.fajr.data.FajrPreferences").getConstructor(Context.class).newInstance(c),s.code);s.day=new SimpleDateFormat("EEEE",l).format(new Date());android.icu.util.IslamicCalendar h=new android.icu.util.IslamicCalendar();h.setCalculationType(android.icu.util.IslamicCalendar.CalculationType.ISLAMIC_UMALQURA);int hoff=c.getSharedPreferences("fajr_prefs",0).getInt("hijri_offset",0);if(hoff!=0)h.add(Calendar.DATE,hoff);s.hday=""+h.get(Calendar.DATE);s.hyear=""+h.get(Calendar.YEAR);s.hmonth=com.example.prayer.HijriDate.INSTANCE.monthName(h.get(Calendar.MONTH)+1,s.code);s.hijri=s.hday+" "+s.hmonth;s.greg=new SimpleDateFormat("d MMMM",l).format(new Date());s.gday=new SimpleDateFormat("d",Locale.ENGLISH).format(new Date());s.gmonth=new SimpleDateFormat("MMMM",l).format(new Date());s.gyear=""+day.get(Calendar.YEAR);return s;}
  static int[] barFillColors(Context c,int id){String k=id>0?c.getSharedPreferences("fajr_prefs",0).getString("widget_bar_color_"+id,null):null;if(k==null)k=c.getSharedPreferences("fajr_prefs",0).getString("widget_bar_color","auto");if("amber".equals(k))return new int[]{0xFFE5B455,0xFFE5B455};if("blue".equals(k))return new int[]{0xFF41A0FF,0xFF3B83FE};if("green".equals(k))return new int[]{0xFF5BC950,0xFF24C55E};if("purple".equals(k))return new int[]{0xFF9747FF,0xFF9747FF};int autoCol=isLight(bgColor(c,id))?0xFF000000:0xFFFFFFFF;return new int[]{autoCol,autoCol};}
 static int wpId=-9;static android.graphics.Bitmap wpBlur=null;
 static android.graphics.Bitmap wallBlur(Context c){
  try{
   android.app.WallpaperManager wm=android.app.WallpaperManager.getInstance(c);
   int id=wm.getWallpaperId(android.app.WallpaperManager.FLAG_SYSTEM);
   if(wpBlur!=null&&id==wpId)return wpBlur;
   android.graphics.drawable.Drawable d=wm.getDrawable();if(d==null)return null;
   int w=d.getIntrinsicWidth(),h=d.getIntrinsicHeight();if(w<=0||h<=0){w=720;h=1280;}
   int sw=48,sh=Math.max(1,48*h/w);
   android.graphics.Bitmap small=android.graphics.Bitmap.createBitmap(sw,sh,android.graphics.Bitmap.Config.ARGB_8888);
   android.graphics.Canvas cv=new android.graphics.Canvas(small);d.setBounds(0,0,sw,sh);d.draw(cv);
   // heavy blur: two box passes over the tiny bitmap, then it is scaled up at draw time
   boxBlur(small,3);boxBlur(small,3);
   wpBlur=small;wpId=id;return wpBlur;
  }catch(Throwable t){return null;}
 }
 static void boxBlur(android.graphics.Bitmap b,int r){
  int w=b.getWidth(),h=b.getHeight();int[] px=new int[w*h];b.getPixels(px,0,w,0,0,w,h);int[] out=new int[w*h];
  for(int y=0;y<h;y++)for(int x=0;x<w;x++){long a=0,rr=0,g=0,bb=0,n=0;for(int dx=-r;dx<=r;dx++){int xx=x+dx;if(xx<0||xx>=w)continue;int p=px[y*w+xx];a+=p>>>24;rr+=(p>>16)&255;g+=(p>>8)&255;bb+=p&255;n++;}out[y*w+x]=(int)((a/n<<24)|(rr/n<<16)|(g/n<<8)|(bb/n));}
  for(int y=0;y<h;y++)for(int x=0;x<w;x++){long a=0,rr=0,g=0,bb=0,n=0;for(int dy=-r;dy<=r;dy++){int yy=y+dy;if(yy<0||yy>=h)continue;int p=out[yy*w+x];a+=p>>>24;rr+=(p>>16)&255;g+=(p>>8)&255;bb+=p&255;n++;}px[y*w+x]=(int)((a/n<<24)|(rr/n<<16)|(g/n<<8)|(bb/n));}
  b.setPixels(px,0,w,0,0,w,h);
 }
 static android.graphics.Bitmap centerCrop(android.graphics.Bitmap src,int w,int h){
 android.graphics.Bitmap out=android.graphics.Bitmap.createBitmap(w,h,android.graphics.Bitmap.Config.ARGB_8888);
 android.graphics.Canvas cv=new android.graphics.Canvas(out);
 float sc=Math.max((float)w/src.getWidth(),(float)h/src.getHeight());
 float dw=src.getWidth()*sc,dh=src.getHeight()*sc;
 android.graphics.RectF dst=new android.graphics.RectF((w-dw)/2f,(h-dh)/2f,(w+dw)/2f,(h+dh)/2f);
 cv.drawBitmap(src,null,dst,new Paint(Paint.FILTER_BITMAP_FLAG));
 return out;
}
static int avgColor(android.graphics.Bitmap b){
  int w=b.getWidth(),h=b.getHeight();long r=0,g=0,bb=0;int n=0;
  for(int y=0;y<h;y+=2)for(int x=0;x<w;x+=2){int p=b.getPixel(x,y);r+=(p>>16)&255;g+=(p>>8)&255;bb+=p&255;n++;}
  return (int)(r/n)<<16|(int)(g/n)<<8|(int)(bb/n);
 }
 static int bgColor(Context c,int id){String k=id>0?c.getSharedPreferences("fajr_prefs",0).getString("widget_bg_color_"+id,null):null;if(k==null)k=c.getSharedPreferences("fajr_prefs",0).getString("widget_bg_color","auto");int rgb;if("black".equals(k))rgb=0x000000;else if("gray".equals(k))rgb=0x2b2b2b;else if("white".equals(k))rgb=0xf6f6f6;else{boolean night=(c.getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES;rgb=night?0x171719:0xf6f6f6;}if("glass".equals(k)){boolean ng=(c.getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES;return ng?0x59101418:0x66F2F2F7;}if("wallblur".equals(k)){android.graphics.Bitmap wb=wallBlur(c);if(wb!=null)return 0xFF000000|avgColor(wb);boolean ng=(c.getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES;return 0xD9000000|(ng?0x171719:0xf6f6f6);}return 0xD9000000|rgb;}
